class LegacyInertModelPresentationAnalyzerTest {
    @TempDir Path tempDir;
    @Test void unrelatedFixedCuboidTesrIsProvenWithoutNames()throws Exception{
        Path jar=tempDir.resolve("static-model.jar");try(JarOutputStream out=new JarOutputStream(Files.newOutputStream(jar))){put(out,"foreign/deco/Tile.class",tile());put(out,"foreign/deco/Client.class",client());put(out,"foreign/deco/Renderer.class",renderer());put(out,"foreign/deco/Model.class",model());put(out,"assets/foreign/textures/entitys/lamp.png",pngHeader(128,64));}
        var topology=new LegacyInertModelBlockAnalyzer.Rule("lamp",null,"foreign/deco/Block","foreign/deco/Tile","LampTile",new LegacyInertModelBlockAnalyzer.Bounds(.2F,0F,.2F,.8F,.9F,.8F),.95F,14,LegacyInertModelBlockAnalyzer.ORIENTATION_PLAYER_YAW_QUADRANT,true,true,1);
        var analysis=new LegacyInertModelPresentationAnalyzer().analyze(jar,topology);assertTrue(analysis.diagnostics().isEmpty(),analysis.diagnostics().toString());var p=analysis.presentation().orElseThrow();
        assertEquals("foreign/deco/Renderer",p.sourceRendererClass());assertEquals("foreign/deco/Model",p.sourceModelClass());assertEquals("foreign:textures/entitys/lamp.png",p.texture());assertEquals(128,p.imageWidth());assertEquals(64,p.imageHeight());assertEquals(64,p.modelTextureWidth());assertEquals(32,p.modelTextureHeight());assertEquals(2,p.cuboids().size());assertEquals(.0625F,p.modelScale());assertEquals(.5F,p.translateX());assertEquals(0F,p.translateY());assertEquals(.5F,p.translateZ());assertEquals(3,p.metadataMask());assertEquals(90F,p.yawDegreesPerMeta());assertTrue(p.inventoryTransformProven());assertEquals(-.7F,p.inventoryTranslateY());assertEquals(1.3F,p.inventoryScale());
        var first=p.cuboids().stream().filter(c->c.field().equals("body")).findFirst().orElseThrow();assertEquals(-3F,first.x());assertEquals(4F,first.pivotY());assertEquals(4F,first.worldY());
    }
    private static byte[] tile(){ClassWriter w=new ClassWriter(0);w.visit(Opcodes.V1_7,Opcodes.ACC_PUBLIC,"foreign/deco/Tile",null,"net/minecraft/tileentity/TileEntity",null);w.visitEnd();return w.toByteArray();}
    private static byte[] client(){ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);w.visit(Opcodes.V1_7,Opcodes.ACC_PUBLIC,"foreign/deco/Client",null,"java/lang/Object",null);MethodVisitor m=w.visitMethod(Opcodes.ACC_PUBLIC,"bind","()V",null,null);m.visitCode();m.visitLdcInsn(Type.getObjectType("foreign/deco/Tile"));m.visitLdcInsn("LampTile");m.visitTypeInsn(Opcodes.NEW,"foreign/deco/Renderer");m.visitInsn(Opcodes.DUP);m.visitMethodInsn(Opcodes.INVOKESPECIAL,"foreign/deco/Renderer","<init>","()V",false);m.visitMethodInsn(Opcodes.INVOKESTATIC,"cpw/mods/fml/client/registry/ClientRegistry","registerTileEntity","(Ljava/lang/Class;Ljava/lang/String;Lnet/minecraft/client/renderer/tileentity/TileEntitySpecialRenderer;)V",false);m.visitInsn(Opcodes.RETURN);m.visitMaxs(0,0);m.visitEnd();w.visitEnd();return w.toByteArray();}
    private static byte[] renderer(){String n="foreign/deco/Renderer",model="foreign/deco/Model";ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);w.visit(Opcodes.V1_7,Opcodes.ACC_PUBLIC,n,null,"net/minecraft/client/renderer/tileentity/TileEntitySpecialRenderer",null);w.visitField(Opcodes.ACC_PRIVATE,"model","L"+model+";",null,null).visitEnd();MethodVisitor c=w.visitMethod(Opcodes.ACC_PUBLIC,"<init>","()V",null,null);c.visitCode();c.visitVarInsn(Opcodes.ALOAD,0);c.visitMethodInsn(Opcodes.INVOKESPECIAL,"net/minecraft/client/renderer/tileentity/TileEntitySpecialRenderer","<init>","()V",false);c.visitVarInsn(Opcodes.ALOAD,0);c.visitTypeInsn(Opcodes.NEW,model);c.visitInsn(Opcodes.DUP);c.visitMethodInsn(Opcodes.INVOKESPECIAL,model,"<init>","()V",false);c.visitFieldInsn(Opcodes.PUTFIELD,n,"model","L"+model+";");c.visitInsn(Opcodes.RETURN);c.visitMaxs(0,0);c.visitEnd();MethodVisitor r=w.visitMethod(Opcodes.ACC_PUBLIC,"render","(Lnet/minecraft/tileentity/TileEntity;DDDF)V",null,null);r.visitCode();r.visitMethodInsn(Opcodes.INVOKESTATIC,"org/lwjgl/opengl/GL11","glPushMatrix","()V",false);r.visitVarInsn(Opcodes.ALOAD,1);r.visitMethodInsn(Opcodes.INVOKEVIRTUAL,"net/minecraft/tileentity/TileEntity","func_145832_p","()I",false);r.visitVarInsn(Opcodes.ISTORE,9);r.visitVarInsn(Opcodes.DLOAD,2);r.visitInsn(Opcodes.D2F);r.visitLdcInsn(.5F);r.visitInsn(Opcodes.FADD);r.visitVarInsn(Opcodes.DLOAD,4);r.visitInsn(Opcodes.D2F);r.visitVarInsn(Opcodes.DLOAD,6);r.visitInsn(Opcodes.D2F);r.visitLdcInsn(.5F);r.visitInsn(Opcodes.FADD);r.visitMethodInsn(Opcodes.INVOKESTATIC,"org/lwjgl/opengl/GL11","glTranslatef","(FFF)V",false);r.visitVarInsn(Opcodes.ILOAD,9);r.visitInsn(Opcodes.ICONST_3);r.visitInsn(Opcodes.IAND);r.visitInsn(Opcodes.I2F);r.visitLdcInsn(90F);r.visitInsn(Opcodes.FMUL);r.visitInsn(Opcodes.FCONST_0);r.visitInsn(Opcodes.FCONST_1);r.visitInsn(Opcodes.FCONST_0);r.visitMethodInsn(Opcodes.INVOKESTATIC,"org/lwjgl/opengl/GL11","glRotatef","(FFFF)V",false);r.visitInsn(Opcodes.FCONST_1);r.visitInsn(Opcodes.FCONST_1);r.visitInsn(Opcodes.FCONST_1);r.visitMethodInsn(Opcodes.INVOKESTATIC,"org/lwjgl/opengl/GL11","glColor3f","(FFF)V",false);r.visitVarInsn(Opcodes.ALOAD,0);r.visitFieldInsn(Opcodes.GETFIELD,n,"model","L"+model+";");r.visitMethodInsn(Opcodes.INVOKEVIRTUAL,model,"draw","()V",false);r.visitMethodInsn(Opcodes.INVOKESTATIC,"org/lwjgl/opengl/GL11","glPopMatrix","()V",false);r.visitInsn(Opcodes.RETURN);r.visitMaxs(0,0);r.visitEnd();MethodVisitor inv=w.visitMethod(Opcodes.ACC_PUBLIC,"renderInv","()V",null,null);inv.visitCode();inv.visitMethodInsn(Opcodes.INVOKESTATIC,"org/lwjgl/opengl/GL11","glPushMatrix","()V",false);inv.visitInsn(Opcodes.FCONST_0);inv.visitLdcInsn(-.7F);inv.visitInsn(Opcodes.FCONST_0);inv.visitMethodInsn(Opcodes.INVOKESTATIC,"org/lwjgl/opengl/GL11","glTranslatef","(FFF)V",false);inv.visitLdcInsn(1.3F);inv.visitLdcInsn(1.3F);inv.visitLdcInsn(1.3F);inv.visitMethodInsn(Opcodes.INVOKESTATIC,"org/lwjgl/opengl/GL11","glScalef","(FFF)V",false);inv.visitVarInsn(Opcodes.ALOAD,0);inv.visitFieldInsn(Opcodes.GETFIELD,n,"model","L"+model+";");inv.visitMethodInsn(Opcodes.INVOKEVIRTUAL,model,"draw","()V",false);inv.visitMethodInsn(Opcodes.INVOKESTATIC,"org/lwjgl/opengl/GL11","glPopMatrix","()V",false);inv.visitInsn(Opcodes.RETURN);inv.visitMaxs(0,0);inv.visitEnd();MethodVisitor s=w.visitMethod(Opcodes.ACC_STATIC,"<clinit>","()V",null,null);s.visitCode();s.visitLdcInsn("foreign:textures/entitys/lamp.png");s.visitInsn(Opcodes.POP);s.visitInsn(Opcodes.RETURN);s.visitMaxs(0,0);s.visitEnd();w.visitEnd();return w.toByteArray();}
    private static byte[] model(){String n="foreign/deco/Model",mr="net/minecraft/client/model/ModelRenderer";ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);w.visit(Opcodes.V1_7,Opcodes.ACC_PUBLIC,n,null,"net/minecraft/client/model/ModelBase",null);w.visitField(Opcodes.ACC_PUBLIC,"body","L"+mr+";",null,null).visitEnd();w.visitField(Opcodes.ACC_PUBLIC,"cap","L"+mr+";",null,null).visitEnd();MethodVisitor c=w.visitMethod(Opcodes.ACC_PUBLIC,"<init>","()V",null,null);c.visitCode();c.visitVarInsn(Opcodes.ALOAD,0);c.visitMethodInsn(Opcodes.INVOKESPECIAL,"net/minecraft/client/model/ModelBase","<init>","()V",false);part(c,n,"body",0,0,-3F,0F,-3F,6,10,6,0F,4F,0F);part(c,n,"cap",0,16,-4F,-1F,-4F,8,1,8,0F,4F,0F);c.visitInsn(Opcodes.RETURN);c.visitMaxs(0,0);c.visitEnd();MethodVisitor draw=w.visitMethod(Opcodes.ACC_PUBLIC,"draw","()V",null,null);draw.visitCode();draw.visitVarInsn(Opcodes.ALOAD,0);draw.visitInsn(Opcodes.ACONST_NULL);for(int i=0;i<5;i++)draw.visitInsn(Opcodes.FCONST_0);draw.visitLdcInsn(.0625F);draw.visitMethodInsn(Opcodes.INVOKEVIRTUAL,n,"func_78088_a","(Lnet/minecraft/entity/Entity;FFFFFF)V",false);draw.visitInsn(Opcodes.RETURN);draw.visitMaxs(0,0);draw.visitEnd();MethodVisitor r=w.visitMethod(Opcodes.ACC_PUBLIC,"func_78088_a","(Lnet/minecraft/entity/Entity;FFFFFF)V",null,null);r.visitCode();render(r,n,"body");render(r,n,"cap");r.visitInsn(Opcodes.RETURN);r.visitMaxs(0,0);r.visitEnd();w.visitEnd();return w.toByteArray();}
    private static void part(MethodVisitor c,String owner,String field,int u,int v,float x,float y,float z,int wi,int he,int de,float px,float py,float pz){String mr="net/minecraft/client/model/ModelRenderer";c.visitVarInsn(Opcodes.ALOAD,0);c.visitTypeInsn(Opcodes.NEW,mr);c.visitInsn(Opcodes.DUP);c.visitVarInsn(Opcodes.ALOAD,0);pushInt(c,u);pushInt(c,v);c.visitMethodInsn(Opcodes.INVOKESPECIAL,mr,"<init>","(Lnet/minecraft/client/model/ModelBase;II)V",false);c.visitFieldInsn(Opcodes.PUTFIELD,owner,field,"L"+mr+";");c.visitVarInsn(Opcodes.ALOAD,0);c.visitFieldInsn(Opcodes.GETFIELD,owner,field,"L"+mr+";");pushFloat(c,x);pushFloat(c,y);pushFloat(c,z);pushInt(c,wi);pushInt(c,he);pushInt(c,de);c.visitMethodInsn(Opcodes.INVOKEVIRTUAL,mr,"func_78789_a","(FFFIII)Lnet/minecraft/client/model/ModelRenderer;",false);c.visitInsn(Opcodes.POP);c.visitVarInsn(Opcodes.ALOAD,0);c.visitFieldInsn(Opcodes.GETFIELD,owner,field,"L"+mr+";");pushFloat(c,px);pushFloat(c,py);pushFloat(c,pz);c.visitMethodInsn(Opcodes.INVOKEVIRTUAL,mr,"func_78793_a","(FFF)V",false);}
    private static void render(MethodVisitor r,String owner,String field){r.visitVarInsn(Opcodes.ALOAD,0);r.visitFieldInsn(Opcodes.GETFIELD,owner,field,"Lnet/minecraft/client/model/ModelRenderer;");r.visitVarInsn(Opcodes.FLOAD,7);r.visitMethodInsn(Opcodes.INVOKEVIRTUAL,"net/minecraft/client/model/ModelRenderer","func_78785_a","(F)V",false);}
    private static void pushFloat(MethodVisitor m,float v){if(v==0F)m.visitInsn(Opcodes.FCONST_0);else if(v==1F)m.visitInsn(Opcodes.FCONST_1);else m.visitLdcInsn(v);}private static void pushInt(MethodVisitor m,int v){if(v>=0&&v<=5)m.visitInsn(Opcodes.ICONST_0+v);else m.visitIntInsn(Opcodes.BIPUSH,v);}private static byte[] pngHeader(int w,int h){byte[] b=new byte[24];byte[] s={(byte)0x89,0x50,0x4E,0x47,0x0D,0x0A,0x1A,0x0A};System.arraycopy(s,0,b,0,8);b[12]='I';b[13]='H';b[14]='D';b[15]='R';ByteBuffer.wrap(b).order(ByteOrder.BIG_ENDIAN).putInt(16,w).putInt(20,h);return b;}private static void put(JarOutputStream out,String name,byte[] bytes)throws Exception{out.putNextEntry(new JarEntry(name));out.write(bytes);out.closeEntry();}
}
